def residual_zoom(image, vocab, base, B, D=2, tau=0.1, phi=0.25, m=1, omega=0.5):
    Y, S, inst, A = base(image, vocab)          # ActiveSAM: map, scores, instance masks, admitted classes
    found = build_found_sets(Y, inst)           # per class: segments already labelled
    queue = PriorityQueue()
    for V in aspect_preserving_roots(image):    # squares of side min(H, W), stride 1/2 side
        T = [c for c in A if area(found[c] & V) < phi * area(V)]
        queue.push(view=V, tested=T, depth=0, prio=INF)
    passes = 0
    while queue and passes < B:
        V, T, d = queue.pop()
        feats = sam3_backbone(resize(crop(image, V), 1008)); passes += 1   # shared, unmasked
        flags = {}
        for c in T:                              # prompts bucketed, 32 per decoder pass
            M = dilate(found[c] & V, tokens=m)   # hide only c's own found segments
            q = presence_after_layer1(feats, prompt[c], key_mask=M)        # residual pooled test
            if q < tau:
                continue                         # negative: c retires in V and its sub-views
            flags[c] = q
            for s in decode_segments(feats, prompt[c], key_mask=M, conf=0.3):
                if area(s & M) > omega * area(s):
                    continue                     # re-detection of a found instance or of the hole
                if not valid(s, V, r_min=2, a_max=0.25, margin=0.5):
                    continue                     # view not authoritative for s
                s = s - found[c] - union(found[k] for k in T if k != c)
                write(Y, s, c, depth=d)          # a coarser write keeps authority
                found[c] = found[c] | s
        if flags and d < D:
            for child in overlapping_quadrants(V, side=0.6, stride=0.4):
                queue.push(view=child, tested=list(flags), depth=d + 1, prio=max(flags.values()))
    return Y                                     # optionally refine with LPOSS+ afterwards
